mapper.select:
SELECT 
  FROM sys10_file
 WHERE sys10_parent_id = 0
   AND COALESCE(sys10_law_type,'') LIKE #{lawType}
   AND COALESCE(sys10_note,'')||sys10_file_nm LIKE #{searchText}
 ORDER BY sys10_law_type, sys10_note, sys10_reg_date DESC

mapper.update:
UPDATE sys10_file
   SET sys10_reg_date = f_sysdate(),
       sys10_note     = #{note}
 WHERE sys10_file_id = #{fileId}
   AND sys10_parent_id = 0

UPDATE sys10_file
   SET sys10_law_type = #{lawType},
       sys10_admin_yn = 'true',
       sys10_note     = #{note}
 WHERE sys10_file_id = #{fileId}
